import { asciiToBytes, bigIntToBytes, bytesToBigInt } from './text-bytes.mjs';

const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

function buildIndexMap() {
  const indexMap = Object.create(null);

  for (let index = 0; index < ALPHABET.length; index += 1) {
    indexMap[ALPHABET[index]] = index;
  }

  return indexMap;
}

const ALPHABET_INDEX = buildIndexMap();

function countLeadingValue(list, expected) {
  let count = 0;

  while (count < list.length && list[count] === expected) {
    count += 1;
  }

  return count;
}

export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export function b58encode(bytes) {
  const leadingZeroCount = countLeadingValue(bytes, 0);
  let value = bytesToBigInt(bytes);
  const encoded = [];

  while (value > 0n) {
    encoded.push(ALPHABET[Number(value % 58n)]);
    value /= 58n;
  }

  encoded.reverse();

  const encodedText = '1'.repeat(leadingZeroCount) + encoded.join('');
  return asciiToBytes(encodedText);
}

export function b58decode(text) {
  const leadingOneCount = countLeadingValue(text, '1');
  let value = 0n;

  for (const char of text) {
    const digit = ALPHABET_INDEX[char];

    if (digit === undefined) {
      throw new ValueError(`Invalid character '${char}'`);
    }

    value = (value * 58n) + BigInt(digit);
  }

  return [
    ...new Array(leadingOneCount).fill(0),
    ...bigIntToBytes(value),
  ];
}

